exportRecipes.export-render.mjs:
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {nalatiMountedFigure} from '<checkouts>/shard-nalati/src/generators/mountedFigure.ts';
import {nativeNalatiDressingPlacements} from '<checkouts>/shard-nalati/src/generators/nativeDressingPlacements.mjs';
import {nalatiGrassBake} from '<checkouts>/shard-nalati/src/generators/grassBake.mjs';
import {grassChannelBytes} from '<checkouts>/shard-nalati/src/generators/grassRows.ts';
const source='<checkouts>/shard-nalati';
const paint=JSON.parse(readFileSync('test/fixtures/frozen/nalati/nalati-poi-paint-original.json','utf8'));
writeFileSync('test/fixtures/frozen/mounted-figure.json',JSON.stringify(nalatiMountedFigure(paint))+'\n');
writeFileSync('test/fixtures/frozen/shape-pins.json',readFileSync(source+'/test/fixtures/nalati-poi-paint-files.json'));
const grass=nalatiGrassBake(new Uint8Array(readFileSync(source+'/public/assets/baked/nalati-grasslands/terrain.bin')),await nativeNalatiDressingPlacements(file=>new Uint8Array(readFileSync(source+'/'+file))));
const files=new Map([...grass.files,...grassChannelBytes().map(blob=>[blob.name,blob.bytes])]);
const rows=structuredClone(grass.rows);for(const tier of ['phone','desktop'])delete rows[tier].channels;
const dir='test/fixtures/frozen/grass';mkdirSync(dir,{recursive:true});
const manifest={};
for(const [name,bytes] of files){const hash=createHash('sha256').update(bytes).digest('hex');writeFileSync(dir+'/'+hash+'.bin',bytes);manifest[name]={file:hash+'.bin',bytes:bytes.length,sha256:hash};}
writeFileSync('test/fixtures/frozen/grass.json',JSON.stringify({rows,files:manifest})+'\n');

