import {mergeProjectBlobs as merge} from '<checkouts>/sharddev/src/sharddev/projectOutput.ts';
import {writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
export function mergeProjectBlobs(...args:Parameters<typeof merge>){
 const inputSha256=createHash('sha256').update(JSON.stringify(args[0])).digest('hex');
 const result=merge(...args);
 writeFileSync('tmp/codex-tc48/decision-worker-product.json',JSON.stringify({inputSha256,sourceCommit:'da2a4ddb564db35b5c3bcba4ba1358de92ced1af',shard:result.shard,assets:[...result.assets].map(([hash,bytes])=>[hash,Buffer.from(bytes).toString('base64')])})+'\n');
 return result;
}
